// does, returning ErrMultipleValues; use Add or ReplaceAll instead.
func (f *File) Set(key Key, value string) error {
	var found []*optionRec

	for _, o := range f.options {
		if o.key.Matches(key) {
			found = append(found, o)
		}
	}

	if len(found) > 1 {
