package config

import "strings"

// parser walks a configuration file byte by byte, recording the position of
// every section header and variable so they can later be spliced in place.
type parser struct {
	data []byte
	pos  int
	line int

	f      *File
	curSec *sectionRec
}

func (p *parser) run() error {
	defer func() {
		if n := len(p.f.sections); n > 0 {
			p.f.sections[n-1].regionEnd = len(p.data)
		}
	}()

	for p.pos < len(p.data) {
		lineStart := p.pos
		p.skipBlank()

		if p.atLineEnd() {
			p.consumeLineEnd()

			continue
		}

		if p.data[p.pos] == '#' || p.data[p.pos] == ';' {
			p.skipToLineEnd()
			p.consumeLineEnd()

			continue
		}

		sawHeader := false

		if p.data[p.pos] == '[' {
			if err := p.parseHeader(lineStart); err != nil {
				return err
			}

			sawHeader = true

			p.skipBlank()

			if p.atLineEnd() || p.data[p.pos] == '#' || p.data[p.pos] == ';' {
				p.curSec.plain = p.atLineEnd()
				p.skipToLineEnd()
				p.consumeLineEnd()
				p.curSec.lineEnd = p.pos
				p.curSec.entryEnd = p.pos

				continue
			}
			// Git allows a variable to follow the header on the same line.
		}

		if err := p.parseVariable(lineStart, !sawHeader); err != nil {
			return err
		}
	}

	return nil
}

func (p *parser) parseHeader(lineStart int) error {
	p.pos++ // consume '['

	start := p.pos
	for p.pos < len(p.data) && (isAlnum(p.data[p.pos]) || p.data[p.pos] == '-' || p.data[p.pos] == '.') {
		p.pos++
	}

	name := string(p.data[start:p.pos])
	if name == "" {
		return p.err()
	}

	var key Key

	p.skipBlank()

	switch {
	case p.pos < len(p.data) && p.data[p.pos] == '"':
		sub, err := p.parseSubsection()
		if err != nil {
			return err
		}

		if !validSectionName(name) {
			return p.err()
		}

		key = Key{Section: name, Subsection: sub, HasSubsection: true}
	case strings.Contains(name, "."):
		// Deprecated "[section.subsection]" form. Git lower-cases the whole
		// header, so the subsection is case-insensitive here only.
		sec, sub, _ := strings.Cut(name, ".")
		if !validSectionName(sec) {
			return p.err()
		}

		key = Key{
			Section: sec,
			// Git folds the whole "[section.subsection]" header, so only in
			// this deprecated form is the subsection case-insensitive.
			Subsection:    strings.ToLower(sub),
			HasSubsection: true,
		}
	default:
		if !validSectionName(name) {
			return p.err()
		}

		key = Key{Section: name}
	}

	p.skipBlank()

	if p.pos >= len(p.data) || p.data[p.pos] != ']' {
		return p.err()
	}

	p.pos++

	sec := &sectionRec{key: key, lineStart: lineStart, headerEnd: p.pos}
	if n := len(p.f.sections); n > 0 {
		// A section occurrence owns the file up to the next header.
		p.f.sections[n-1].regionEnd = lineStart
	}

	p.f.sections = append(p.f.sections, sec)
	p.curSec = sec

	return nil
}

func (p *parser) parseSubsection() (string, error) {
	p.pos++ // consume '"'

	var b strings.Builder

	for {
		if p.pos >= len(p.data) || p.data[p.pos] == '\n' {
			return "", p.err()
		}

		c := p.data[p.pos]
		if c == 0 {
			return "", p.err()
		}

		if c == '"' {
			p.pos++

			return b.String(), nil
		}

		if c == '\\' {
			p.pos++

			if p.pos >= len(p.data) || p.data[p.pos] == '\n' {
				return "", p.err()
			}

			b.WriteByte(p.data[p.pos])
			p.pos++

			continue
		}

		b.WriteByte(c)

		p.pos++
	}
}

func (p *parser) parseVariable(lineStart int, alone bool) error {
	if p.curSec == nil {
		// A variable before any section header has no key Git could name.
		return p.err()
	}

	nameStart := p.pos
	for p.pos < len(p.data) && (isAlnum(p.data[p.pos]) || p.data[p.pos] == '-') {
		p.pos++
	}

	name := string(p.data[nameStart:p.pos])
	if !validVariableName(name) {
		return p.err()
	}

	o := &optionRec{
		key: Key{
			Section:       p.curSec.key.Section,
			Subsection:    p.curSec.key.Subsection,
			HasSubsection: p.curSec.key.HasSubsection,
			Name:          name,
		},
		lineStart: lineStart,
		nameEnd:   p.pos,
		alone:     alone,
	}

	p.skipBlank()

	if p.pos < len(p.data) && p.data[p.pos] == '=' {
		p.pos++
		p.skipBlank()

		o.valueStart = p.pos

		value, err := p.parseValue()
		if err != nil {
			return err
		}

		o.value = value
	} else {
		o.valueless = true
		o.valueStart = o.nameEnd

		// Only a comment may follow a bare variable name. Anything else is
		// a malformed line, which git rejects rather than guessing at.
		if !p.atLineEnd() && p.data[p.pos] != '#' && p.data[p.pos] != ';' {
			return p.err()
		}
	}

	p.skipToLineEnd()

	o.logicalEnd = p.pos
	if p.pos < len(p.data) && p.data[p.pos] == '\r' {
		// git replaces the CR along with the value, so a rewritten line ends
		// up with a bare LF even in a CRLF file.
		o.logicalEnd++
	}

	p.consumeLineEnd()
	o.lineEnd = p.pos

	if !alone {
		p.curSec.lineEnd = p.pos
	}

	o.secIdx = len(p.f.sections) - 1
	p.f.options = append(p.f.options, o)
	p.curSec.entryEnd = p.pos

	return nil
}

// parseValue reads a variable's value, honouring quoted runs, backslash
// escapes and backslash-newline continuations, and trimming unquoted trailing
// whitespace.
func (p *parser) parseValue() (string, error) { //nolint:gocognit // parser state machine
	var (
		b        strings.Builder
		inQuote  bool
		lastKeep int
	)

	for p.pos < len(p.data) {
		c := p.data[p.pos]
		if c == 0 {
			return "", p.err()
		}

		switch {
		case c == '\n' || (c == '\r' && p.peekIsLF()):
			if inQuote {
				return "", p.err()
			}

			return b.String()[:lastKeep], nil

		case c == '"':
			inQuote = !inQuote
			p.pos++

		case c == '\\':
			p.pos++

			if p.pos >= len(p.data) {
				return "", p.err()
			}

			e := p.data[p.pos]
			if e == '\r' && p.peekIsLF() {
				p.pos++
				e = '\n'
			}

			if e == '\n' {
				// Line continuation: the value carries on below.
				p.pos++
				p.line++

				continue
			}

			decoded, ok := unescape(e)
			if !ok {
				return "", p.err()
			}

			b.WriteByte(decoded)

			p.pos++

			lastKeep = b.Len()

		case !inQuote && (c == '#' || c == ';'):
			return b.String()[:lastKeep], nil

		default:
			b.WriteByte(c)

			p.pos++

			if inQuote || (c != ' ' && c != '\t') {
				lastKeep = b.Len()
			}
		}
	}

	if inQuote {
		return "", p.err()
	}

	return b.String()[:lastKeep], nil
}

func unescape(c byte) (byte, bool) {
	switch c {
	case 'n':
		return '\n', true
	case 't':
		return '\t', true
	case 'b':
		return '\b', true
	case '\\':
		return '\\', true
	case '"':
		return '"', true
	}

	return 0, false
}

func (p *parser) skipBlank() {
	for p.pos < len(p.data) && (p.data[p.pos] == ' ' || p.data[p.pos] == '\t') {
		p.pos++
	}
}

func (p *parser) atLineEnd() bool {
	return p.pos >= len(p.data) || p.data[p.pos] == '\n' || (p.data[p.pos] == '\r' && p.peekIsLF())
}

func (p *parser) peekIsLF() bool {
	return p.pos+1 < len(p.data) && p.data[p.pos+1] == '\n'
}

func (p *parser) skipToLineEnd() {
	for !p.atLineEnd() {
		p.pos++
	}
}

func (p *parser) consumeLineEnd() {
	if p.pos < len(p.data) && p.data[p.pos] == '\r' {
		p.pos++
	}

	if p.pos < len(p.data) && p.data[p.pos] == '\n' {
		p.pos++
		p.line++
	}
}

func (p *parser) err() error {
	return &ParseError{Line: p.line}
}
// Package config parses and edits Git configuration files while preserving
// their original formatting.
//
// The go-git raw config decoder/encoder pair round-trips through a canonical
// representation: it drops every comment and cannot represent an empty
// subsection name ("[user \"\"]" is folded into "[user]"). Both are lossy in
// ways that silently corrupt a user's file, so config file mutation here is
// done by splicing bytes in the original document instead.
package config

import "strings"

// Key is a parsed configuration key such as "remote.origin.url".
//
// Every field holds the spelling it was given, because git writes a variable
// using the spelling from the command line rather than folding it. Matching,
// by contrast, ignores case for section and variable names, so compare keys
// with Matches and never with ==.
type Key struct {
	// Section is the section name as spelled. Section names match
	// case-insensitively in Git.
	Section string
	// Subsection is the subsection name. Subsection names match
	// case-sensitively in Git.
	Subsection string
	// HasSubsection distinguishes "user..name", which addresses the empty
	// subsection [user ""], from "user.name", which addresses [user].
	HasSubsection bool
	// Name is the variable name as spelled. Variable names match
	// case-insensitively in Git.
	Name string
}

// KeyNoSectionError reports a key with no '.' separator, matching git's
// "key does not contain a section" diagnostic.
type KeyNoSectionError struct{ Key string }

func (e *KeyNoSectionError) Error() string {
	return "key does not contain a section: " + e.Key
}

// KeyNoVariableError reports a key that ends at the section separator, matching
// git's "key does not contain variable name" diagnostic.
type KeyNoVariableError struct{ Key string }

func (e *KeyNoVariableError) Error() string {
	return "key does not contain variable name: " + e.Key
}

// KeyInvalidError reports a key whose section or variable name uses characters
// Git does not accept.
type KeyInvalidError struct{ Key string }

func (e *KeyInvalidError) Error() string {
	return "invalid key: " + e.Key
}

// ParseKey splits a fully qualified configuration key.
//
// Git splits at the first and the last '.': everything between them is the
// subsection, which may itself contain dots ("remote.team.one.url" addresses
// [remote "team.one"] url). A key with exactly two components has no
// subsection; "a..b" has an empty one.
func ParseKey(key string) (Key, error) {
	first := strings.IndexByte(key, '.')
	if first < 0 {
		return Key{}, &KeyNoSectionError{Key: key}
	}

	last := strings.LastIndexByte(key, '.')
	if last == len(key)-1 {
		return Key{}, &KeyNoVariableError{Key: key}
	}

	k := Key{
		Section: key[:first],
		Name:    key[last+1:],
	}

	if first != last {
		k.Subsection = key[first+1 : last]
		k.HasSubsection = true

		if !validSubsectionName(k.Subsection) {
			return Key{}, &KeyInvalidError{Key: key}
		}
	}

	if !validSectionName(k.Section) || !validVariableName(k.Name) {
		return Key{}, &KeyInvalidError{Key: key}
	}

	return k, nil
}

// String renders the key in the form ParseKey accepts.
func (k Key) String() string {
	if k.HasSubsection {
		return k.Section + "." + k.Subsection + "." + k.Name
	}

	return k.Section + "." + k.Name
}

// Matches reports whether k addresses the same variable as other. Section and
// variable names compare case-insensitively; subsection names compare
// byte-for-byte, and an empty subsection is distinct from none at all.
func (k Key) Matches(other Key) bool {
	return k.sameSection(other) && strings.EqualFold(k.Name, other.Name)
}

// sameSection reports whether both keys address the same section header.
func (k Key) sameSection(other Key) bool {
	return strings.EqualFold(k.Section, other.Section) &&
		k.HasSubsection == other.HasSubsection &&
		k.Subsection == other.Subsection
}

// validSectionName accepts alphanumerics and '-'. Unlike variable names, a
// section name may start with a digit.
func validSectionName(s string) bool {
	if s == "" {
		return false
	}

	for i := range len(s) {
		if !isAlnum(s[i]) && s[i] != '-' {
			return false
		}
	}

	return true
}

// validVariableName accepts alphanumerics and '-', and requires an alphabetic
// first character.
func validVariableName(s string) bool {
	if s == "" || !isAlpha(s[0]) {
		return false
	}

	for i := range len(s) {
		if !isAlnum(s[i]) && s[i] != '-' {
			return false
		}
	}

	return true
}

func validSubsectionName(s string) bool {
	return !strings.ContainsAny(s, "\x00\n")
}

func isAlpha(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isAlnum(c byte) bool {
	return isAlpha(c) || (c >= '0' && c <= '9')
}

