package main

import (
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/go-git/go-git/v6/plumbing/client"
	"github.com/go-git/go-git/v6/plumbing/transport"
	"github.com/go-git/go-git/v6/plumbing/transport/ssh"
	"github.com/go-git/go-git/v6/utils/trace"
	"github.com/spf13/cobra"
	gossh "golang.org/x/crypto/ssh"
)

var rootCmd = &cobra.Command{
	Use:     "gogit [<args>] <command>",
	Short:   "gogit is a Git CLI that uses go-git as its backend.",
	Version: "0.1.0-gogit",
	RunE: func(_ *cobra.Command, _ []string) error {
		// Real git exits 1 when invoked with no subcommand. test-lib.sh
		// relies on this to detect a working git binary. We deliberately
		// omit printing usage so summary-mode harness output stays clean
		// during test-lib's sanity checks.
		os.Exit(1)

		return nil
	},
	DisableFlagsInUseLine: true,
	SilenceUsage:          true,
	SilenceErrors:         true,
}

// envToTarget maps what environment variables can be used
// to enable specific trace targets.
var envToTarget = map[string]trace.Target{
	"GIT_TRACE":             trace.General,
	"GIT_TRACE_PACKET":      trace.Packet,
	"GIT_TRACE_SSH":         trace.SSH,
	"GIT_TRACE_PERFORMANCE": trace.Performance,
}

func init() {
	// Set up tracing
	var target trace.Target

	for k, v := range envToTarget {
		if ok, _ := strconv.ParseBool(os.Getenv(k)); ok {
			target |= v
		}
	}

	trace.SetTarget(target)
}

func init() {
	rootCmd.PersistentFlags().StringArrayVarP(&configOverridesRaw, "config", "c", nil,
		"Override a configuration value for the duration of this command (key=value, may be repeated)")
	rootCmd.PersistentPreRunE = func(_ *cobra.Command, _ []string) error {
		return applyConfigOverridesFromFlags()
	}
}

func main() {
	for _, arg := range os.Args[1:] {
		if arg == "--exec-path" || strings.HasPrefix(arg, "--exec-path=") {
			exe, err := os.Executable()
			if err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(1)
			}

			fmt.Println(filepath.Dir(exe))

			return
		}
	}

	err := rootCmd.Execute()
	if err != nil {
		// Some commands need git's own exit statuses, and git stays
		// silent for several of them, so gitExitError carries both the
		// code and whether anything is printed.
		var gerr *gitExitError
		if errors.As(err, &gerr) {
			if gerr.msg != "" {
				fmt.Fprintln(os.Stderr, gerr.msg)
			}

			os.Exit(gerr.code)
		}

		var rerr *transport.RemoteError
		if errors.As(err, &rerr) {
			fmt.Fprintln(os.Stderr, rerr)
		} else {
			fmt.Fprintln(os.Stderr, err)
		}

		os.Exit(1)
	}
}

func defaultClientOptions(u *url.URL) []client.Option {
	if u == nil {
		return nil
	}

	switch u.Scheme {
	case "file", "git":
		// Do nothing.
	case "ssh":
		if u.User == nil {
			return nil
		}

		a, err := ssh.NewSSHAgentAuth(u.User.Username())
		if err != nil {
			return nil
		}

		switch u.Host {
		case "localhost", "127.0.0.1":
			// Ignore host key verification for localhost.
			a.HostKeyCallback = gossh.InsecureIgnoreHostKey()
		}

		return []client.Option{client.WithSSHAuth(a)}
	case "http", "https":
	}

	return nil
}
package main

import (
	"fmt"
	"strings"
	"sync"

	gitconfig "github.com/go-git/cli/internal/plumbing/format/config"
	"github.com/go-git/go-git/v6/config"
)

var (
	configOverridesRaw []string
	configOverrides    = map[string]string{}
	configImplicit     = map[string]bool{}
	configOverrideMu   sync.Mutex

	// configOverrideList keeps the -c overrides in the order they were given
	// and with their keys normalised, which the config command needs to
	// report repeated values and to match subsection spellings. The map above
	// stays keyed by the raw string for the existing callers.
	configOverrideList []configOverride
)

// configOverride is a single -c key=value pair with its key parsed.
type configOverride struct {
	key      gitconfig.Key
	value    string
	implicit bool
}

// splitKV splits "<key>=<value>" into (key, value, true). Invalid input
// (no '=' or empty key) returns ("", "", false). Empty value is allowed.
func splitKV(s string) (string, string, bool) {
	idx := strings.IndexByte(s, '=')
	if idx <= 0 {
		return "", "", false
	}

	return s[:idx], s[idx+1:], true
}

func applyConfigOverride(key, value string) {
	applyConfigOverrideValue(key, value, false)
}

func applyConfigOverrideValue(key, value string, implicit bool) {
	configOverrideMu.Lock()
	defer configOverrideMu.Unlock()

	configOverrides[key] = value
	configImplicit[key] = implicit
}

func resetConfigOverrides() {
	configOverrideMu.Lock()
	defer configOverrideMu.Unlock()

	configOverrides = map[string]string{}
	configImplicit = map[string]bool{}
	configOverridesRaw = nil
	configOverrideList = nil
}

// applyConfigOverridesFromFlags parses raw `-c k=v` values previously captured
// by cobra and populates the override map.
func applyConfigOverridesFromFlags() error {
	for _, raw := range configOverridesRaw {
		k, v, ok := splitKV(raw)
		implicit := !ok

		if !ok {
			k = raw
			v = ""

			if k == "" {
				return fmt.Errorf("invalid -c value %q", raw)
			}
		}

		key, kerr := gitconfig.ParseKey(k)
		if kerr != nil {
			return fmt.Errorf("invalid -c value %q: %w", raw, kerr)
		}

		configOverrideList = append(configOverrideList, configOverride{
			key: key, value: v, implicit: implicit,
		})

		applyConfigOverrideValue(k, v, implicit)
	}

	return nil
}

// hasConfigOverride reports whether key has been explicitly set via -c.
func hasConfigOverride(key string) bool {
	configOverrideMu.Lock()
	_, ok := configOverrides[key]
	configOverrideMu.Unlock()

	return ok
}

// configBool returns the effective boolean value for the given config key.
// Lookup order: -c override > defaultVal. Empty-string override means false.
// repoCfg is accepted for future expansion but not consulted in v1.
//
//nolint:unparam // repoCfg is part of the shared config helper contract.
func configBool(key string, repoCfg *config.Config, defaultVal bool) bool {
	configOverrideMu.Lock()
	v, ok := configOverrides[key]
	implicit := configImplicit[key]
	configOverrideMu.Unlock()

	_ = repoCfg

	if ok {
		if implicit {
			return true
		}

		return strings.EqualFold(v, "true")
	}

	return defaultVal
}
package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// gitDirName is the name of a repository's git directory inside a work tree.
const gitDirName = ".git"

var errNoRepository = errors.New("not a git repository")

// findGitDir locates the repository's git directory.
func findGitDir() (string, error) {
	path, _, err := discoverGitDir()

	return path, err
}

