package main

import (
	"fmt"
	"strings"
	"sync"

	"github.com/go-git/go-git/v6/config"
)

var (
	configOverridesRaw []string
	configOverrides    = map[string]string{}
	configOverrideMu   sync.Mutex
)

// splitKV splits "<key>=<value>" into (key, value, true). Invalid input
// (no '=' or empty key) returns ("", "", false). Empty value is allowed.
func splitKV(s string) (string, string, bool) {
	idx := strings.IndexByte(s, '=')
	if idx <= 0 {
		return "", "", false
	}

	return s[:idx], s[idx+1:], true
}

func applyConfigOverride(key, value string) {
	configOverrideMu.Lock()
	defer configOverrideMu.Unlock()

	configOverrides[key] = value
}

func resetConfigOverrides() {
	configOverrideMu.Lock()
	defer configOverrideMu.Unlock()

	configOverrides = map[string]string{}
	configOverridesRaw = nil
}

// applyConfigOverridesFromFlags parses raw `-c k=v` values previously captured
// by cobra and populates the override map.
func applyConfigOverridesFromFlags() error {
	for _, raw := range configOverridesRaw {
		k, v, ok := splitKV(raw)
		if !ok {
			return fmt.Errorf("invalid -c value %q (want key=value)", raw)
		}

		applyConfigOverride(k, v)
	}

	return nil
}

// hasConfigOverride reports whether key has been explicitly set via -c.
func hasConfigOverride(key string) bool {
	configOverrideMu.Lock()
	_, ok := configOverrides[key]
	configOverrideMu.Unlock()

	return ok
}

// configBool returns the effective boolean value for the given config key.
// Lookup order: -c override > defaultVal. Empty-string override means false.
// repoCfg is accepted for future expansion but not consulted in v1.
//
//nolint:unparam // key/repoCfg used by future callers (Task 7+).
func configBool(key string, repoCfg *config.Config, defaultVal bool) bool {
	configOverrideMu.Lock()
	v, ok := configOverrides[key]
	configOverrideMu.Unlock()

	_ = repoCfg

	if ok {
		return strings.EqualFold(v, "true")
	}

	return defaultVal
}
	// Determine pack hash from the path name (pack-<hash>.pack).
	base := filepath.Base(packPath)
	packHashStr := strings.TrimPrefix(strings.TrimSuffix(base, ".pack"), "pack-")
	packHash := plumbing.NewHash(packHashStr)

	idxPath := indexPackOutput
	if idxPath == "" {
		idxPath = packPath[:len(packPath)-len(".pack")] + ".idx"
	}

	if err := writeIdxFile(idxPath, idx, 2, packHash); err != nil {
		return fmt.Errorf("write idx: %w", err)
	}

	// Determine rev-index write:
	//   1. --no-rev-index is a hard override → never write
	//   2. --rev-index flag → always write
	//   3. pack.writeReverseIndex from -c override (key present) → use it
	//   4. pack.writeReverseIndex from .git/config → read raw file
	var writeRev bool

	switch {
	case indexPackNoRevIndex:
		writeRev = false
	case indexPackRevIndex:
		writeRev = true
	default:
		if hasConfigOverride("pack.writeReverseIndex") {
			writeRev = configBool("pack.writeReverseIndex", nil, false)
		} else if gitDir, gerr := findGitDir(); gerr == nil {
			cfgPath := filepath.Join(gitDir, "config")
			writeRev = readConfigBool(cfgPath, "pack", "writeReverseIndex", false)
		}
	}

	if writeRev {
		var revPath string

		if indexPackOutput != "" {
			if base2, ok := strings.CutSuffix(indexPackOutput, ".idx"); ok {
				revPath = base2 + ".rev"
			} else {
				revPath = indexPackOutput + ".rev"
			}
		} else {
			revPath = packPath[:len(packPath)-len(".pack")] + ".rev"
		}

		if err := writeRevIndex(idx, revPath); err != nil {
			return fmt.Errorf("write rev index: %w", err)
		}
	}

