	)
	if err != nil || stdout != "Alice\n" || stderr != "" {
		t.Fatalf("stdin read: stdout %q, stderr %q, err %v", stdout, stderr, err)
	}

	stdout, stderr, err = runGogitEnvStdin(
		t,
		base,
		configEnv(home),
		"",
		cmdConfig,
		subSet,
		flagFile,
		"-",
		keyUserName,
