	}

	if _, err := os.Stat(filepath.Join(base, "-")); !os.IsNotExist(err) {
		t.Fatalf("stdin write created a literal '-' file: %v", err)
	}
}

func TestConfigUnsetRemovesSameLineSection(t *testing.T) {
