func mustKey(t *testing.T, s string) config.Key {
	t.Helper()

	k, err := config.ParseKey(s)
	if err != nil {
		t.Fatalf("ParseKey(%q): %v", s, err)
	}

	return k
}

func mustParse(t *testing.T, src string) *config.File {
	t.Helper()

	f, err := config.Parse([]byte(src))
	if err != nil {
		t.Fatalf("Parse(%q): %v", src, err)
	}

