// parseValue reads a variable's value, honouring quoted runs, backslash
// escapes and backslash-newline continuations, and trimming unquoted trailing
// whitespace.
func (p *parser) parseValue() (string, error) { //nolint:gocognit // parser state machine
	var (
		b        strings.Builder
		inQuote  bool
		lastKeep int
	)

	for p.pos < len(p.data) {
		c := p.data[p.pos]
		if c == 0 {
			return "", p.err()
		}

		switch {
		case c == '\n' || (c == '\r' && p.peekIsLF()):
			if inQuote {
				return "", p.err()
			}

			return b.String()[:lastKeep], nil

		case c == '"':
			inQuote = !inQuote
			p.pos++

		case c == '\\':
			p.pos++

			if p.pos >= len(p.data) {
				return "", p.err()
			}

			e := p.data[p.pos]
			if e == '\r' && p.peekIsLF() {
				p.pos++
				e = '\n'
			}

			if e == '\n' {
				// Line continuation: the value carries on below.
				p.pos++
				p.line++

				continue
			}

			decoded, ok := unescape(e)
			if !ok {
				return "", p.err()
			}

			b.WriteByte(decoded)

			p.pos++

			lastKeep = b.Len()

		case !inQuote && (c == '#' || c == ';'):
			return b.String()[:lastKeep], nil

		default:
			b.WriteByte(c)

			p.pos++

			if inQuote || (c != ' ' && c != '\t') {
				lastKeep = b.Len()
			}
		}
	}

	if inQuote {
		return "", p.err()
	}

	return b.String()[:lastKeep], nil
}

