func matchesPOSIXClass(name string, value byte, insensitive bool) bool {
	switch name {
	case "alnum":
		return isASCIIAlpha(value) || value >= '0' && value <= '9'
	case "alpha":
		return isASCIIAlpha(value)
	case "blank":
		return value == ' ' || value == '\t'
	case "cntrl":
		return value < 0x20 || value == 0x7f
	case "digit":
		return value >= '0' && value <= '9'
	case "graph":
		return value > ' ' && value < 0x7f
	case "lower":
		return value >= 'a' && value <= 'z' || insensitive && value >= 'A' && value <= 'Z'
	case "print":
		return value >= ' ' && value < 0x7f
	case "punct":
		return value > ' ' && value < 0x7f && !isASCIIAlpha(value) && !(value >= '0' && value <= '9')
	case "space":
		return strings.ContainsRune(" \t\n\v\f\r", rune(value))
	case "upper":
		return value >= 'A' && value <= 'Z' || insensitive && value >= 'a' && value <= 'z'
	case "xdigit":
		return value >= '0' && value <= '9' || value >= 'a' && value <= 'f' || value >= 'A' && value <= 'F'
	default:
		return false
	}
}

func isASCIIAlpha(value byte) bool {
	return value >= 'a' && value <= 'z' || value >= 'A' && value <= 'Z'
}

func equalWildByte(left, right byte, insensitive bool) bool {
	return foldWildByte(left, insensitive) == foldWildByte(right, insensitive)
}

